test('REQ-1-3-2#3: REQ-1-3-2 -the requested workflow', async ({ page }) => {
  const fileName = `export-state-${u()}.csv`;
  const csv = 'Alpha,Beta\n1,2\n';

  await importCsv(page, fileName, csv);

  await cell(page, 'A1').click();
  await expect(tab(page, 'Sheet1')).toHaveAttribute('aria-selected', 'true');
  await expectCellText(page, 'A1', 'Alpha');
  await expect(formulaBar(page)).toHaveValue('Alpha');

  const { filename, text } = await exportCsv(page);
  expect(filename.endsWith('.csv')).toBeTruthy();
  expect(text.replace(/\r\n/g, '\n')).toBe('Alpha,Beta\n1,2\n');

  await expect(tab(page, 'Sheet1')).toHaveAttribute('aria-selected', 'true');
  await expectCellText(page, 'A1', 'Alpha');
  await expect(formulaBar(page)).toHaveValue('Alpha');

  await page.reload();
  await expect(tab(page, 'Sheet1')).toHaveAttribute('aria-selected', 'true');
  await expectCellText(page, 'A1', 'Alpha');
  await expect(formulaBar(page)).toHaveValue('Alpha');
});

test('REQ-2-1-3: REQ-2-1-3 -the requested workflow,the requested workflow', async ({ page }) => {
  const name = `wb-${u()}`;
  const newSheetName = `Data-${u()}`;
  await createBlankWorkbook(page, name);
  await addWorksheet(page, 'Sheet2');

  await openWorksheetMenu(page, 'Sheet1');
  await page.getByRole('menuitem', { name: 'Rename', exact: true }).click();
  await expect(page.getByLabel('Worksheet name', { exact: true })).toHaveValue('Sheet1');
  await page.getByLabel('Worksheet name', { exact: true }).fill(newSheetName);
  await page.getByRole('button', { name: 'Save', exact: true }).click();

  await expect(page.getByRole('tab', { name: newSheetName, exact: true })).toBeVisible();
  await expect(page.getByRole('tab', { name: newSheetName, exact: true })).toHaveAttribute('aria-selected', 'true');
  await expect(page.getByRole('tab', { name: 'Sheet1', exact: true })).toHaveCount(0);

  await page.reload();
  await expect(page.getByRole('tab', { name: newSheetName, exact: true })).toBeVisible();
  await expect(page.getByRole('tab', { name: newSheetName, exact: true })).toHaveAttribute('aria-selected', 'true');
});

test('REQ-3-2-2#7: REQ-3-2-2 -the requested workflow', async ({ page }) => {
  await createBlankWorkbook(page, 't3_2_2col_' + u());

  await enterCell(page, 'A1', 'x');
  await page.getByRole('columnheader', { name: 'A', exact: true }).click({ button: 'right' });
  await page.getByRole('menuitem', { name: 'Insert 1 column right', exact: true }).click();

  await expect(cell(page, 'B1')).toHaveText('x');
  await expect(cell(page, 'A1')).toHaveText('');

  await page.getByRole('button', { name: 'Undo', exact: true }).click();
  await expect(cell(page, 'A1')).toHaveText('x');

  await page.keyboard.press('Control+y');
  await expect(cell(page, 'B1')).toHaveText('x');
  await expect(cell(page, 'A1')).toHaveText('');

  await page.reload();
  await expect(cell(page, 'B1')).toHaveText('x');
});

